dependencies {
    testImplementation 'org.springframework.restdocs:spring-restdocs-mockmvc'
}

test {
    outputs.dir snippetsDir
    useJUnitPlatform()
}

asciidoctor {
    inputs.dir snippetsDir
    dependsOn test
}

@WebMvcTest(CustomerController.class)
@AutoConfigureRestDocs(outputDir = "build/generated-snippets")
public class CustomerControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @Test
    public void shouldDocumentCreateCustomer() throws Exception {
        this.mockMvc.perform(post("/customers")
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"name\": \"John Doe\", \"email\": \"john@example.com\"}"))
            .andExpect(status().isOk())
            .andDo(document("create-customer",
                    requestFields(
                        fieldWithPath("name").description("The name of the customer"),
                        fieldWithPath("email").description("The email of the customer")
                    ),
                    responseFields(
                        fieldWithPath("id").description("The ID of the customer"),
                        fieldWithPath("name").description("The name of the customer"),
                        fieldWithPath("email").description("The email of the customer")
                    )
            ));
    }
}

@Test
public void shouldDocumentConsistency() throws Exception {
    this.mockMvc.perform(get("/customers/1"))
        .andExpect(status().isOk())
        .andDo(document("get-customer",
            responseFields(
                fieldWithPath("id").description("Customer ID"),
                fieldWithPath("name").description("Customer name"),
                fieldWithPath("email").description("Customer email")
            )));
}

mockMvc.perform(get("/secure/customers")
        .header("Authorization", "Bearer token"))
    .andDo(document("secure-customers",
        requestHeaders(
            headerWithName("Authorization").description("Bearer token for authentication")
        )));

